docker exec atmosphera-hub_php php artisan tinker --execute="
\$indoorTotal = \App\Models\Fabric::whereHas('fabricCategory.category1', function(\$q) {
    \$q->where('name->it', 'Indoor');
})->count();
echo 'Total indoor fabrics: ' . \$indoorTotal . PHP_EOL;

\$products = \App\Models\Product::whereHas('fabrics')->with('fabrics.fabricCategory.category1')->get();
foreach (\$products as \$p) {
    \$indoorFabricsCount = \$p->fabrics->filter(function(\$f) {
        return optional(optional(\$f->fabricCategory)->category1)->getTranslation('name','it') === 'Indoor';
    })->count();
    if (\$indoorFabricsCount > 0 && \$indoorFabricsCount < \$indoorTotal) {
        echo \$p->id . ' - ' . \$p->name . ' -> indoor fabrics: ' . \$indoorFabricsCount . '/' . \$indoorTotal . PHP_EOL;
    }
}
" 2>&1 | head -60

